import { APIClient } from '../api/client.js';
import { SearchParams, SearchResult } from '../models/search.js';
import { logger } from '../utils/logger.js';
import { config } from '../config/index.js';

const api = new APIClient();

export const searchTools = [
  {
    name: 'search_knowledge',
    description: 'Search knowledge base with AI processing to get intelligent answers with references',
    parameters: {
      type: 'object',
      properties: {
        question: {
          type: 'string',
          description: 'The question to search for in the knowledge base'
        },
        topic_ids: {
          type: 'array',
          items: { type: 'string' },
          description: 'Knowledge base topic IDs (currently supports only one). If not provided, uses default from GET_NOTE_TOPIC_ID env var'
        },
        deep_seek: {
          type: 'boolean',
          description: 'Enable deep thinking mode for better answers',
          default: true
        },
        refs: {
          type: 'boolean',
          description: 'Include references to source materials',
          default: false
        },
        history: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              content: { type: 'string' },
              role: { type: 'string', enum: ['user', 'assistant'] }
            }
          },
          description: 'Conversation history for follow-up questions',
          default: []
        }
      },
      required: ['question', 'topic_ids']
    },
    handler: async (args) => {
      try {
        logger.info(`Searching knowledge: ${args.question}`);
        
        // 如果没有提供topic_ids，使用默认的
        if (!args.topic_ids || args.topic_ids.length === 0) {
          if (config.knowledgeBase.topicIds.length > 0) {
            args.topic_ids = config.knowledgeBase.topicIds;
            logger.info(`Using default topic_ids: ${config.knowledgeBase.topicIds.join(', ')}`);
          }
        }
        
        const params = new SearchParams(args);
        params.validate();
        
        const result = await api.searchKnowledge(
          params.question,
          params.topicIds,
          {
            deep_seek: params.deepSeek,
            refs: params.refs,
            history: params.history
          }
        );
        
        // 解析响应数据
        const responseData = result.c || result;
        const answers = responseData.answers || '';
        const thinkingProcess = responseData.thinking_process || '';
        
        let content = '';
        if (thinkingProcess) {
          content += `**思考过程：**\n${thinkingProcess}\n\n`;
        }
        content += `**回答：**\n${answers}`;
        
        return {
          content: [{
            type: 'text',
            text: content
          }]
        };
      } catch (error) {
        logger.error(`Knowledge search failed: ${error.message}`);
        throw error;
      }
    }
  },

  {
    name: 'search_knowledge_stream',
    description: 'Search knowledge base with streaming response for real-time answers',
    parameters: {
      type: 'object',
      properties: {
        question: {
          type: 'string',
          description: 'The question to search for in the knowledge base'
        },
        topic_ids: {
          type: 'array',
          items: { type: 'string' },
          description: 'Knowledge base topic IDs (currently supports only one)'
        },
        deep_seek: {
          type: 'boolean',
          description: 'Enable deep thinking mode for better answers',
          default: true
        },
        refs: {
          type: 'boolean',
          description: 'Include references to source materials',
          default: false
        },
        history: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              content: { type: 'string' },
              role: { type: 'string', enum: ['user', 'assistant'] }
            }
          },
          description: 'Conversation history for follow-up questions',
          default: []
        }
      },
      required: ['question', 'topic_ids']
    },
    handler: async (args) => {
      try {
        logger.info(`Streaming knowledge search: ${args.question}`);
        
        // 如果没有提供topic_ids，使用默认的
        if (!args.topic_ids || args.topic_ids.length === 0) {
          if (config.knowledgeBase.topicIds.length > 0) {
            args.topic_ids = config.knowledgeBase.topicIds;
            logger.info(`Using default topic_ids: ${config.knowledgeBase.topicIds.join(', ')}`);
          }
        }
        
        const params = new SearchParams(args);
        params.validate();
        
        const stream = await api.searchKnowledgeStream(
          params.question,
          params.topicIds,
          {
            deep_seek: params.deepSeek,
            refs: params.refs,
            history: params.history
          }
        );
        
        // 处理流式响应
        const reader = stream.getReader();
        const decoder = new TextDecoder();
        let fullContent = '';
        let references = [];
        let thinkingTime = null;
        
        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            
            const chunk = decoder.decode(value);
            const lines = chunk.split('\n');
            
            for (const line of lines) {
              if (line.startsWith('data: ')) {
                try {
                  const data = JSON.parse(line.slice(6));
                  
                  if (data.msg_type === 1) {
                    fullContent += data.data?.msg || '';
                  } else if (data.msg_type === 105) {
                    references = data.data?.ref_list || [];
                  } else if (data.msg_type === 22) {
                    thinkingTime = data.data?.msg;
                  }
                } catch (e) {
                  logger.warn('Failed to parse stream data:', e);
                }
              }
            }
          }
        } finally {
          reader.releaseLock();
        }
        
        let result = fullContent;
        if (thinkingTime) {
          result = `**思考时长：** ${thinkingTime}ms\n\n${result}`;
        }
        if (references.length > 0) {
          result += '\n\n**参考资料：**\n';
          references.forEach((ref, index) => {
            result += `${index + 1}. ${ref.title || '未命名'}\n`;
          });
        }
        
        return {
          content: [{
            type: 'text',
            text: result
          }]
        };
      } catch (error) {
        logger.error(`Stream knowledge search failed: ${error.message}`);
        throw error;
      }
    }
  }
];